  "privRights": "Vaše práva",
  "noticeReopen": "Oznámenie o úložisku",
  "noticeLabel": "Oznámenie o úložisku prehliadača",
  "noticeText": "Cook používa úložisko prehliadača pre funkcie varenia a prihlásenia, ktoré používate. Nepridáva sa žiadne reklamné ani analytické úložisko.",
  "noticeClose": "Zavrieť oznámenie o úložisku",
  "privDraftLabel": "Koncept — aktualizované 28. októbra 2026.",
  "privDraft": "Funkcie účtu sa práve testujú. Nižšie uvedené údaje o prevádzkovateľovi a službách treba doplniť pred verejným spustením.",
  "privWho1": "Cook prevádzkuje [úradný názov a poštová adresa prevádzkovateľa]. S otázkami a žiadosťami o ochrane súkromia sa obráťte na [e-mail pre ochranu súkromia]. Tieto údaje treba doplniť pred otvorením registrácie.",
  "privWhat1": "Keď si vytvoríte účet, používame váš e-mail, identifikátor účtu, záznamy o overení heslom a stav potvrdenia, aby sme mohli účet poskytovať a chrániť. Heslá spracúva poskytovateľ overovania ako bezpečné hashe; Cook neukladá čitateľné heslá. Ukladáme usporiadanie kuchyne, zvolený jazyk, motív a jednotky, aby sme obnovili vaše nastavenia na všetkých zariadeniach. Na účet je potrebný e-mail a heslo; recepty môžete prezerať aj bez účtu.",
  "privWhat2": "Spracúvanie účtu a nastavení je nevyhnutné na poskytovanie služby účtu, o ktorú žiadate (čl. 6 ods. 1 písm. b) GDPR). Obmedzené záznamy na zabezpečenie a prevenciu zneužitia sa môžu spracúvať na základe oprávnených záujmov (čl. 6 ods. 1 písm. f)), v nevyhnutnom rozsahu a po vyvážení záujmov. E-maily na overenie a obnovenie hesla sú servisné správy, nie marketing. Funkcia účtu nepridáva reklamu ani analytiku.",
  "privStorage1": "Cook používa sessionStorage na prenos vašej kuchyne, postupu varenia a volieb medzi stránkami v tej istej karte. Keď ste prihlásení, uchováva aj vašu prihlasovaciu reláciu. Prehliadač tieto údaje zvyčajne vymaže po skončení relácie karty, ale obnovenie relácie prehliadača ich môže zachovať. Odhlásenie vymaže údaje karty Cook. Zatvorenie oznámenia o úložisku sa pamätá len v danej karte. Vlastné skripty Cook nenastavujú cookies. Vaši poskytovatelia hostingu alebo služieb môžu vykonávať vlastné bezpečnostné spracúvanie, ktoré treba pred spustením zdokumentovať.",
  "privStorage2": "OK a tlačidlo na zatvorenie oznámenia o úložisku oznámenie iba zatvoria. Nepovoľujú analytiku, reklamu ani iné voliteľné sledovanie. Akékoľvek budúce nepotrebné ukladanie bude vyžadovať samostatnú voľbu ešte pred začatím, s rovnako jednoduchým odmietnutím a odvolaním.",
  "privOther1": "Súčasná hlasová funkcia zoznamu receptov sa podľa vašej IP adresy pýta služby country.is na približnú krajinu, aby zvolila jazyk rozpoznávania reči. Ak používate rozpoznávanie z mikrofónu, prehliadač môže posielať zvuk svojmu poskytovateľovi rozpoznávania reči. Suroviny môžete aj napísať. Títo poskytovatelia, ich zásady a právny základ týchto funkcií musia byť pred verejným spustením preskúmané.",
  "privProviders1": "Plánovaný poskytovateľ účtov: Supabase (spravovaný PostgreSQL a overovanie) so zvolenou oblasťou databázy v EÚ. Poskytovateľ e-mailu: [poskytovateľ]. Hosting webu: [poskytovateľ]. Prevádzkovateľ musí potvrdiť skutočných poskytovateľov, zmluvy o spracúvaní, subdodávateľov, umiestnenie logov a prípadné prenosy mimo EHP. Oblasť databázy v EÚ sama osebe nevylučuje medzinárodné prenosy. V príslušných prípadoch uveďte rozhodnutie o primeranosti alebo zmluvné záruky a ako získať ich kópiu.",
  "privRetention1": "Nastavenia účtu sa uchovávajú, kým je váš účet aktívny. O vymazanie môžete požiadať cez vyššie uvedený kontakt na ochranu súkromia. Pred spustením musí prevádzkovateľ stanoviť postup vybavovania žiadostí o vymazanie, uplynutie platnosti neoverených účtov a dobu uchovávania bezpečnostných logov a záloh. Vymazané údaje môžu zostať v zálohách s obmedzeným prístupom až do konca zdokumentovanej doby uchovávania.",
  "privRights1": "V závislosti od platných podmienok môžete požadovať prístup, opravu, vymazanie, obmedzenie spracúvania alebo prenosnosť, prípadne namietať proti spracúvaniu na základe oprávneného záujmu. Obráťte sa na vyššie uvedeného prevádzkovateľa; na žiadosti sa zvyčajne odpovedá do jedného mesiaca a prípadné zákonné predĺženie sa vysvetlí. Môžete podať sťažnosť dozornému orgánu vrátane maďarského NAIH na naih.hu. Cook nepoužíva nastavenia účtu na automatizované rozhodovanie s právnymi alebo podobne významnými účinkami.",
